static int cmpInt(const void* a, const void* b) {
    int p = *(const int*) a, q = *(const int*) b;
    return (p > q) - (p < q);
}

bool hasDuplicate(int* badges, int badgesSize) {
    int* s = malloc(badgesSize * sizeof(int));
    memcpy(s, badges, badgesSize * sizeof(int));
    qsort(s, badgesSize, sizeof(int), cmpInt);
    bool dup = false;
    for (int i = 0; i + 1 < badgesSize && !dup; i++) dup = s[i] == s[i + 1];
    free(s);
    return dup;
}

