// C has no built-in hash set, so here is a small one: open addressing with
// linear probing over a power-of-two table.
typedef struct { int key; bool used; } Slot;

static unsigned slotOf(int key, unsigned mask) {
    unsigned long long h = (unsigned long long) (long long) key * 0x9E3779B97F4A7C15ULL;
    return (unsigned) (h >> 32) & mask;
}

bool hasDuplicate(int* badges, int badgesSize) {
    unsigned cap = 1;
    while (cap < 2u * badgesSize) cap <<= 1;
    Slot* seen = calloc(cap, sizeof(Slot));
    bool dup = false;
    for (int i = 0; i < badgesSize && !dup; i++) {
        unsigned s = slotOf(badges[i], cap - 1);
        while (seen[s].used && seen[s].key != badges[i]) s = (s + 1) & (cap - 1);
        if (seen[s].used) dup = true;
        else seen[s] = (Slot) {badges[i], true};
    }
    free(seen);
    return dup;
}
